javascript:(async()=>{let response=await fetch("https://cdn.jsdelivr.net/gh/cpxcristian/_nonsenseprojects@develop/nonsensecdns/mh.list.json");const sagas=await response.json(),list={},range=(start,end)=>Array.from({length:end-start+1},(_,i)=>start+i);[...document.querySelectorAll(".post-body a")].filter(el=>/Cap[ií]tulo/i.test(el.textContent)).map(el=>{const chapter=el.href.substring(el.href.indexOf("capitulo-")+9,el.href.indexOf(".html"));isNaN(chapter)||(list[chapter]=el.href)});const displayContent=params=>{let content="";return params.forEach(el=>{if(content+=`<details><summary>${void 0!==el.range_chapters?el.range_chapters:"+"} ${el.name} ${void 0!==el.chapters?el.chapters.length:""}</summary><section>`,void 0!==el.data)content+=displayContent(el.data);else{const[rI,rE]=el.range_chapters.split("-").map(Number);content+=`\n            <ul>\n              ${range(rI,rE).map(ch=>`\n                <li>\n                  <span \n                    class="item-link" \n                    role="link" \n                    data-id="${ch}" \n                    onClick="openElement(this, '${list[ch]}')"\n                  >\n                    Capitulo-${ch}\n                  </span>\n                </li>`)}\n            </ul>`.replaceAll(">,",">")}content+="</section></details>"}),content};document.querySelector("body").innerHTML=`\n      <nav id="sidebar" class="col-12 col-xl-2">\n        <section class="list">${displayContent(sagas)}</section>\n        <button class="floating-button" id="hide-sidebar" onclick="hideSidebar(this)">x</button>\n      </nav>\n      <section id="content" class="col d-md-block"></section>\n    `;const addCSS=css=>document.head.appendChild(document.createElement("style")).innerHTML=css;addCSS("body{font-size:18px!important;height:99vh!important;display:flex!important;padding:0!important;min-height:initial!important}#sidebar{height:100vh;position:relative!important}#sidebar .list{overflow:hidden scroll;height:100%}.col-2{flex:0 0 auto;width:16.66666667%}.col-12{flex:0 0 auto;width:100%}.col{flex:1 0 0%;width:100%}.d-none{display:none!important}details{cursor:pointer;padding-left:12px}.item-link{color:#f4a900}.item-link.selected,.item-link:hover{color:#c60}.floating-button{position:absolute;width:26px;height:45px;top:0;right:-26px;border-radius:0 8px 8px 0;z-index:9999;display:flex;align-items:center;text-align:center;padding-left:8px;cursor:pointer;border:none}#hide-sidebar{background-color:gray;color:#fff!important}.hidden{width:0!important;height:0!important;display:block!important}@media (max-width:767px){.floating-button{right:0!important;transform:scaleX(-1)}.hidden .floating-button{right:-26px!important;transform:scaleX(1)}}@media (min-width:768px){.d-md-block{display:block!important}}@media (min-width:1200px){.col-xl-2{flex:0 0 auto;width:16.66666667%}}")})(),window.hideSidebar=void 0!==window.hideSidebar?window.hideSidebar:param=>{let c=param.closest("#sidebar");c.classList.contains("hidden")?(c.classList.add("col-2"),c.classList.remove("hidden"),document.querySelector("#content").classList.add("d-none")):(c.classList.remove("col-2"),c.classList.add("hidden"),document.querySelector("#content").classList.remove("d-none"))},window.openElement=void 0!==window.openElement?window.openElement:(t,p)=>{document.querySelectorAll("span.item-link").forEach(el=>el.classList.remove("selected")),t.classList.add("selected");let id=t.getAttribute("data-id");history.replaceState(null,null,`${window.location.origin}${window.location.pathname}?chapter=${id}`),document.querySelector("#content").innerHTML=`<embed src="${p}" style="width:100%;height:100%;">`};void(0);